const j = $input.first().json;
const DIR_RE = /^\/opt\/loot\/asm\/(_sys|[a-z0-9][a-z0-9_-]{0,39})\/\d{8}T\d{6}Z-[0-9a-f]{4}\/[a-z_]{2,20}$/;
if (!DIR_RE.test(String(j.job_dir ?? ''))) throw new Error(`Refusing job_dir: ${j.job_dir}`);
if (!j.script || typeof j.script !== 'string') throw new Error('No script supplied');
const max = Math.min(Math.max(parseInt(j.max_minutes ?? 120, 10) || 120, 1), 600);
const script_b64 = Buffer.from(j.script, 'utf8').toString('base64');
if (script_b64.length > 100000) throw new Error(`Script too large for command line (${script_b64.length} bytes)`);
return [{ json: { job_dir: j.job_dir, stage: j.job_dir.split('/').pop(), max_minutes: max, script_b64 } }];

const job = $('Validate Job').first().json;
const r = JSON.parse($input.first().json.stdout);
const timedOut = r.rc === 124;
if (r.rc !== 0 && !timedOut) {
  const tail = String(r.log_tail ?? '').replace(/\s+/g, ' ').trim().slice(-800);
  throw new Error(`Stage ${job.stage} failed (rc=${r.rc}). Log tail: ${tail}`);
}
return [{ json: { stage: job.stage, job_dir: job.job_dir, rc: r.rc, timed_out: timedOut, result: r.result ?? {} } }];
